const buildMetricDeltaColumn = (groupKey: string, key: string, deltaHeader: string): ColDef => ({
  colId: `delta_${groupKey}_${key}`,
  field: `delta_${groupKey}_${key}`,
  headerName: deltaHeader,
  ...COMPACT_NUMBER_FILTER_COL_DEF,
  ...compareScoreColDef,
